    it (`parts.append(x)`, `d['k'] = v`, `req.messages[0]['content']
    .extend(...)`): any method may change the object it is called on, as
    for a module constant (#4166). Cached per function node."""
    entry = _WRITES.get(id(fn))
    if entry is not None and entry[0] is fn:
        return entry[1]
    out = _local_values(fn)
    bound = set(out) - set(_params(fn))
    alias_groups = {k: {k} for k in bound}
    seen_writes = {k: {id(v) for v in vals} for k, vals in out.items()}
    loop_stack = []
    exc_stack = []
    try_types = (ast.Try, getattr(ast, "TryStar", ast.Try))

    def add_write(m, val):
        if id(val) not in seen_writes[m]:
            seen_writes[m].add(id(val))
            out[m].append(val)

    def record_exc_state():
        for acc in exc_stack:
            for k in bound:
                acc[k].update(alias_groups[k])

    def clone_state(state=None):
        src = alias_groups if state is None else state
        return {k: set(v) for k, v in src.items()}

    def restore_state(state):
        for k in bound:
            alias_groups[k] = set(state[k])
        record_exc_state()

    def join_states(*states):
        return {
            k: set().union(*(s[k] for s in states if s is not None))
            for k in bound
        }

    def kill_alias(name):
        if name in bound:
            for m in list(alias_groups[name]):
                if m != name:
                    alias_groups[m].discard(name)
            alias_groups[name] = {name}
            record_exc_state()

    def bind_alias(target_name, source_name):
        if target_name == source_name:
            return
        kill_alias(target_name)
        if target_name in bound and source_name in bound:
            sources = set(alias_groups[source_name])
            alias_groups[target_name] |= sources
            for m in sources:
                alias_groups[m].add(target_name)
            record_exc_state()

    def visit(node):
        if isinstance(node, ast.Continue):
            if loop_stack:
                loop_stack[-1][0].append(clone_state())
            return
        if isinstance(node, ast.Break):
            if loop_stack:
                loop_stack[-1][1].append(clone_state())
            return
        if isinstance(node, (ast.If, ast.IfExp)):
            visit(node.test)
            saved = clone_state()
            if isinstance(node, ast.If):
                for stmt in node.body:
                    visit(stmt)
                after_body = clone_state()
                restore_state(saved)
                for stmt in node.orelse:
                    visit(stmt)
            else:
                visit(node.body)
                after_body = clone_state()
                restore_state(saved)
                visit(node.orelse)
            restore_state(join_states(after_body, alias_groups))
            return
        if isinstance(node, try_types):
            s_in = clone_state()
            s_try_accum = clone_state(s_in)
            exc_stack.append(s_try_accum)
            try:
                for stmt in node.body:
                    visit(stmt)
            finally:
                exc_stack.pop()
            s_after_body = clone_state()
            s_orelse_accum = clone_state(s_after_body)
            exc_stack.append(s_orelse_accum)
            try:
                for stmt in node.orelse:
                    visit(stmt)
            finally:
                exc_stack.pop()
            s_after_orelse = clone_state()
            handler_exits = []
            s_handlers_accum = {k: set() for k in bound}
            exc_stack.append(s_handlers_accum)
            try:
                for handler in node.handlers:
                    restore_state(s_try_accum)
                    if handler.type is not None:
                        visit(handler.type)
                    if handler.name:
                        kill_alias(handler.name)
                    for stmt in handler.body:
                        visit(stmt)
                    handler_exits.append(clone_state())
            finally:
                exc_stack.pop()
            s_normal = join_states(s_after_orelse, *handler_exits)
            if node.finalbody:
                restore_state(join_states(s_normal, s_try_accum, s_orelse_accum, s_handlers_accum))
                for stmt in node.finalbody:
                    visit(stmt)
                restore_state(s_normal)
                for stmt in node.finalbody:
                    visit(stmt)
            else:
                restore_state(s_normal)
            return
        if isinstance(node, ast.Match):
            visit(node.subject)
            s_fallthrough = clone_state()
            case_exits = []
            has_irrefutable = False
            for case in node.cases:
                restore_state(s_fallthrough)
                is_irrefutable_pattern = (
                    isinstance(case.pattern, ast.MatchAs) and case.pattern.pattern is None
                )
                if is_irrefutable_pattern:
                    if case.guard is None:
                        has_irrefutable = True
                    if case.pattern.name:
                        if isinstance(node.subject, ast.Name):
                            bind_alias(case.pattern.name, node.subject.id)
                            if case.pattern.name in bound:
                                add_write(case.pattern.name, node.subject)
                        else:
                            kill_alias(case.pattern.name)
                else:
                    for sub in ast.walk(case.pattern):
                        p_name = (
                            getattr(sub, "name", None)
                            if type(sub).__name__ in {"MatchAs", "MatchStar"}
                            else (getattr(sub, "rest", None) if type(sub).__name__ == "MatchMapping" else None)
                        )
                        if p_name:
                            if isinstance(node.subject, ast.Name):
                                bind_alias(p_name, node.subject.id)
                            else:
                                kill_alias(p_name)
                if case.guard is not None:
                    visit(case.guard)
                if not (is_irrefutable_pattern and case.guard is None):
                    s_fallthrough = join_states(s_fallthrough, alias_groups)
                for stmt in case.body:
                    visit(stmt)
                case_exits.append(clone_state())
            if not has_irrefutable:
                case_exits.append(s_fallthrough)
            restore_state(join_states(*case_exits))
            return
        if isinstance(node, (ast.For, ast.AsyncFor, ast.While)):
            s_entry = clone_state()
            max_iters = len(bound) * len(bound) + 4
            break_states = []
            for _ in range(max_iters):
                restore_state(s_entry)
                cont_states = []
                cur_breaks = []
                loop_stack.append((cont_states, cur_breaks))
                try:
                    if isinstance(node, (ast.For, ast.AsyncFor)):
                        visit(node.iter)
                        for sub in ast.walk(node.target):
                            if isinstance(sub, ast.Name) and isinstance(sub.ctx, ast.Store):
                                kill_alias(sub.id)
                    else:
                        visit(node.test)
                    for stmt in node.body:
                        visit(stmt)
                finally:
                    loop_stack.pop()
                break_states = cur_breaks
                s_next = join_states(s_entry, alias_groups, *cont_states)
                if s_next == s_entry:
                    break
                s_entry = s_next
            restore_state(s_entry)
            if isinstance(node, (ast.For, ast.AsyncFor)):
                visit(node.iter)
            else:
                visit(node.test)
            for stmt in node.orelse:
                visit(stmt)
            restore_state(join_states(alias_groups, *break_states))
            return
        if isinstance(node, (ast.With, ast.AsyncWith)):
            for item in node.items:
                visit(item.context_expr)
                if item.optional_vars is not None:
                    for sub in ast.walk(item.optional_vars):
                        if isinstance(sub, ast.Name) and isinstance(sub.ctx, ast.Store):
                            kill_alias(sub.id)
            s_with_accum = clone_state()
            exc_stack.append(s_with_accum)
            try:
                for stmt in node.body:
                    visit(stmt)
            finally:
                exc_stack.pop()
            restore_state(join_states(alias_groups, s_with_accum))
            return
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and node is not fn:
            for dec in node.decorator_list:
                visit(dec)
            if isinstance(node, ast.ClassDef):
                for b in node.bases:
                    visit(b)
                for kw in node.keywords:
                    visit(kw)
            else:
                for d in list(node.args.defaults) + [kd for kd in node.args.kw_defaults if kd is not None]:
                    visit(d)
            s_outer = clone_state()
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                for p_name in _params(node):
                    kill_alias(p_name)
            for stmt in node.body:
                visit(stmt)
            restore_state(s_outer)
            kill_alias(node.name)
            return
        if isinstance(node, ast.Delete):
            for t in node.targets:
                if isinstance(t, ast.Name) and t.id in bound:
                    kill_alias(t.id)
                else:
                    visit(t)
            return
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and _holder(node.func.value) in bound:
            vals = ([a.value if isinstance(a, ast.Starred) else a for a in node.args]
                    + [k.value for k in node.keywords])
            for m in alias_groups[_holder(node.func.value)]:
                for v in vals:
                    add_write(m, v)
        elif isinstance(node, (ast.Assign, ast.AnnAssign, ast.AugAssign, ast.NamedExpr)) and node.value is not None:
            visit(node.value)
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            for t in targets:
                if isinstance(t, (ast.Subscript, ast.Attribute)) and _holder(t) in bound:
                    visit(t)
                    for m in alias_groups[_holder(t)]:
                        add_write(m, node.value)
                elif isinstance(node, ast.AugAssign) and isinstance(t, ast.Name) and t.id in bound:
                    for m in alias_groups[t.id] - {t.id}:
                        add_write(m, node.value)
                elif isinstance(t, ast.Name) and t.id in bound:
                    if isinstance(node.value, ast.Name):
                        bind_alias(t.id, node.value.id)
                    else:
                        kill_alias(t.id)
                elif isinstance(t, (ast.Tuple, ast.List)):
                    for sub in ast.walk(t):
                        if isinstance(sub, ast.Name) and sub.id in bound:
                            kill_alias(sub.id)
                else:
                    visit(t)
            return
        for child in ast.iter_child_nodes(node):
            visit(child)

    visit(fn)
    _WRITES[id(fn)] = (fn, out)
    return out

derive_model_facing.source:
def derive_model_facing(wrote: dict[str, list[str]]) -> dict[str, list[str]]:
    """The top-level `data_sheets_schema` modules whose text reaches a model
    (#4085): each module the data flow (`text_flow`) carried one of its own
    string literals from into model text, with what carried it. A module
    that only passes on what it is given, or whose literals are punctuation
    and whitespace (a separator, a rule line), writes none."""
    out: dict[str, list[str]] = {}
    for rel, labels in sorted(wrote.items()):
        name = _package_module_name(Path(rel))
        if name is not None and rel.startswith("src/data_sheets_schema/"):
            out.setdefault(name, []).extend(labels)
    return out

is_violation.source:
def is_violation(hit: dict) -> bool:
    """A gc_project hit with no exception that some gating approach counts:
    model-facing text or a code branch/table there (`gates_in`)."""
    return hit["category"] == "gc_project" and hit.get("exception") is None and bool(hit.get("gates_in"))

_derive_uncached.source:
def _derive_uncached(inputs, schema_rows, project, limits, *, captured_assets=None, _schema_reuse=None):
    if type(inputs) is not dict or not _REQUIRED <= set(inputs) <= _REQUIRED | _OPTIONAL:
        raise ValueError("captured input roster differs from protocol")
    raw = {key: _unblob(value) for key, value in inputs.items()}
    for key in ("original_full", "original_core"):
        if key in raw:
            omissions._mapping(raw[key], key)
    if ("source_manifest" in raw) != (project is not None):
        raise ValueError("source manifest and explicit project must be captured together")
    authority = None
    if "source_manifest" in raw:
        authority = _source_authority(raw["source_manifest"], project)
    _exact(limits, {"max_paths", "max_inventory_bytes", "max_workers", "max_output_tokens", "max_request_bytes"}, "limits")
    snapshot = _snapshot(schema_rows)
    if captured_assets is None:
        prepared = omissions.prepare(record=raw["original_full"], bundle=raw["bundle"],
            manifest=raw["manifest"], receipt=raw["receipt"], context=raw["context"],
            schema_path=snapshot.sources[0][1], schema_snapshot=snapshot,
            max_output_tokens=limits["max_output_tokens"], max_request_bytes=limits["max_request_bytes"])
    else:
        prepared = omissions._prepare(record=raw["original_full"], bundle=raw["bundle"],
            manifest=raw["manifest"], receipt=raw["receipt"], context=raw["context"],
            schema_path=snapshot.sources[0][1], schema_snapshot=snapshot,
            max_output_tokens=limits["max_output_tokens"], max_request_bytes=limits["max_request_bytes"],
            captured_assets=captured_assets,
            _catalog=(_schema_reuse.for_snapshot(snapshot) if type(_schema_reuse) is _SchemaReuse else None))
    plan = batches.make_plan(raw["original_full"].decode("utf-8"), version=2,
        **{k: limits[k] for k in ("max_paths", "max_inventory_bytes", "max_workers")})
    contracts = {stage: {"contract": output_format.contract(stage, version=2),
                         "rendered": output_format.render(stage, version=2),
                         "saved_response": {"kind": f"typed_audit_{stage}_response_v1",
                             "required_fields": ["kind", "packet_sha256", "request_sha256", "response",
                                                 "worker_id" if stage == "worker" else "typed_index_sha256"],
                             "response_encoding": "Exact UTF-8 inner JSON bytes as base64, sha256 and bytes.",
                             "authority": "A declared request/response association, not provider authentication."}}
                 for stage in ("worker", "integration")}
    shared = _json({"protocol": audit_protocol.select(audit_protocol.TYPED),
        "original_full": raw["original_full"].decode("utf-8"),
        "original_core": raw.get("original_core", b"").decode("utf-8") or None,
        "bundle": raw["bundle"].decode("utf-8"), "manifest": raw["manifest"].decode("utf-8"),
        "receipt": raw["receipt"].decode("utf-8"), "context": prepared.request()["payload"]["context"],
        "schema": {k: v for k, v in prepared.request()["payload"]["schema"].items()
                   if k not in ("classes", "slots")}, "registered_provenance": authority}).decode("utf-8")
    workers = {worker["id"]: _json({"stage": "worker", "shared_context_sha256": _sha(shared.encode()),
        "plan_sha256": plan["sha256"], "assignment": worker, "inventory": plan["inventory"],
        "output_contract": contracts["worker"]}).decode("utf-8") for worker in plan["workers"]}
    for tail in workers.values():
        if len((shared + tail).encode()) > limits["max_request_bytes"]:
            raise ValueError("complete worker request exceeds max_request_bytes")
    return {"plan": plan, "omission_request": prepared.request(), "contracts": contracts,
            "requests": {"assembly_rule": "shared_context UTF-8 bytes followed by the selected stage UTF-8 bytes",
                         "shared_context": shared, "workers": workers},
            "registered_provenance": authority}, raw, prepared

_local_writes.source:
def _local_writes(fn) -> dict[str, list[ast.AST]]:
    """What becomes part of each local of a function, for the data flow
    (#4085): the value of every assignment to it (plain, unpacked, annotated
    or augmented), the iterable of a `for` loop that binds it, and, for a
    name the function binds that is not a parameter, the arguments of every
    method call on it and every value assigned to an item or attribute of
    it (`parts.append(x)`, `d['k'] = v`, `req.messages[0]['content']
    .extend(...)`): any method may change the object it is called on, as
    for a module constant (#4166). Cached per function node."""
    entry = _WRITES.get(id(fn))
    if entry is not None and entry[0] is fn:
        return entry[1]
    out = _local_values(fn)
    bound = set(out) - set(_params(fn))
    alias_groups = {k: {k} for k in bound}
    seen_writes = {k: {id(v) for v in vals} for k, vals in out.items()}
    loop_stack = []
    exc_stack = []
    try_types = (ast.Try, getattr(ast, "TryStar", ast.Try))

    def add_write(m, val):
        if id(val) not in seen_writes[m]:
            seen_writes[m].add(id(val))
            out[m].append(val)

    def record_exc_state():
        for acc in exc_stack:
            for k in bound:
                acc[k].update(alias_groups[k])

    def clone_state(state=None):
        src = alias_groups if state is None else state
        return {k: set(v) for k, v in src.items()}

    def restore_state(state):
        for k in bound:
            alias_groups[k] = set(state[k])
        record_exc_state()

    def join_states(*states):
        return {
            k: set().union(*(s[k] for s in states if s is not None))
            for k in bound
        }

    def kill_alias(name):
        if name in bound:
            for m in list(alias_groups[name]):
                if m != name:
                    alias_groups[m].discard(name)
            alias_groups[name] = {name}
            record_exc_state()

    def bind_alias(target_name, source_name):
        if target_name == source_name:
            return
        kill_alias(target_name)
        if target_name in bound and source_name in bound:
            sources = set(alias_groups[source_name])
            alias_groups[target_name] |= sources
            for m in sources:
                alias_groups[m].add(target_name)
            record_exc_state()

    def visit(node):
        if isinstance(node, ast.Continue):
            if loop_stack:
                loop_stack[-1][0].append(clone_state())
            return
        if isinstance(node, ast.Break):
            if loop_stack:
                loop_stack[-1][1].append(clone_state())
            return
        if isinstance(node, (ast.If, ast.IfExp)):
            visit(node.test)
            saved = clone_state()
            if isinstance(node, ast.If):
                for stmt in node.body:
                    visit(stmt)
                after_body = clone_state()
                restore_state(saved)
                for stmt in node.orelse:
                    visit(stmt)
            else:
                visit(node.body)
                after_body = clone_state()
                restore_state(saved)
                visit(node.orelse)
            restore_state(join_states(after_body, alias_groups))
            return
        if isinstance(node, try_types):
            s_in = clone_state()
            s_try_accum = clone_state(s_in)
            exc_stack.append(s_try_accum)
            try:
                for stmt in node.body:
                    visit(stmt)
            finally:
                exc_stack.pop()
            s_after_body = clone_state()
            s_orelse_accum = clone_state(s_after_body)
            exc_stack.append(s_orelse_accum)
            try:
                for stmt in node.orelse:
                    visit(stmt)
            finally:
                exc_stack.pop()
            s_after_orelse = clone_state()
            handler_exits = []
            s_handlers_accum = {k: set() for k in bound}
            exc_stack.append(s_handlers_accum)
            try:
                for handler in node.handlers:
                    restore_state(s_try_accum)
                    if handler.type is not None:
                        visit(handler.type)
                    if handler.name:
                        kill_alias(handler.name)
                    for stmt in handler.body:
                        visit(stmt)
                    handler_exits.append(clone_state())
            finally:
                exc_stack.pop()
            s_normal = join_states(s_after_orelse, *handler_exits)
            if node.finalbody:
                restore_state(join_states(s_normal, s_try_accum, s_orelse_accum, s_handlers_accum))
                for stmt in node.finalbody:
                    visit(stmt)
                restore_state(s_normal)
                for stmt in node.finalbody:
                    visit(stmt)
            else:
                restore_state(s_normal)
            return
        if isinstance(node, ast.Match):
            visit(node.subject)
            s_fallthrough = clone_state()
            case_exits = []
            has_irrefutable = False
            for case in node.cases:
                restore_state(s_fallthrough)
                is_irrefutable_pattern = (
                    isinstance(case.pattern, ast.MatchAs) and case.pattern.pattern is None
                )
                if is_irrefutable_pattern:
                    if case.guard is None:
                        has_irrefutable = True
                    if case.pattern.name:
                        if isinstance(node.subject, ast.Name):
                            bind_alias(case.pattern.name, node.subject.id)
                            if case.pattern.name in bound:
                                add_write(case.pattern.name, node.subject)
                        else:
                            kill_alias(case.pattern.name)
                else:
                    for sub in ast.walk(case.pattern):
                        p_name = (
                            getattr(sub, "name", None)
                            if type(sub).__name__ in {"MatchAs", "MatchStar"}
                            else (getattr(sub, "rest", None) if type(sub).__name__ == "MatchMapping" else None)
                        )
                        if p_name:
                            if isinstance(node.subject, ast.Name):
                                bind_alias(p_name, node.subject.id)
                            else:
                                kill_alias(p_name)
                if case.guard is not None:
                    visit(case.guard)
                if not (is_irrefutable_pattern and case.guard is None):
                    s_fallthrough = join_states(s_fallthrough, alias_groups)
                for stmt in case.body:
                    visit(stmt)
                case_exits.append(clone_state())
            if not has_irrefutable:
                case_exits.append(s_fallthrough)
            restore_state(join_states(*case_exits))
            return
        if isinstance(node, (ast.For, ast.AsyncFor, ast.While)):
            s_entry = clone_state()
            max_iters = len(bound) * len(bound) + 4
            break_states = []
            for _ in range(max_iters):
                restore_state(s_entry)
                cont_states = []
                cur_breaks = []
                loop_stack.append((cont_states, cur_breaks))
                try:
                    if isinstance(node, (ast.For, ast.AsyncFor)):
                        visit(node.iter)
                        for sub in ast.walk(node.target):
                            if isinstance(sub, ast.Name) and isinstance(sub.ctx, ast.Store):
                                kill_alias(sub.id)
                    else:
                        visit(node.test)
                    for stmt in node.body:
                        visit(stmt)
                finally:
                    loop_stack.pop()
                break_states = cur_breaks
                s_next = join_states(s_entry, alias_groups, *cont_states)
                if s_next == s_entry:
                    break
                s_entry = s_next
            restore_state(s_entry)
            if isinstance(node, (ast.For, ast.AsyncFor)):
                visit(node.iter)
            else:
                visit(node.test)
            for stmt in node.orelse:
                visit(stmt)
            restore_state(join_states(alias_groups, *break_states))
            return
        if isinstance(node, (ast.With, ast.AsyncWith)):
            for item in node.items:
                visit(item.context_expr)
                if item.optional_vars is not None:
                    for sub in ast.walk(item.optional_vars):
                        if isinstance(sub, ast.Name) and isinstance(sub.ctx, ast.Store):
                            kill_alias(sub.id)
            s_with_accum = clone_state()
            exc_stack.append(s_with_accum)
            try:
                for stmt in node.body:
                    visit(stmt)
            finally:
                exc_stack.pop()
            restore_state(join_states(alias_groups, s_with_accum))
            return
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and node is not fn:
            for dec in node.decorator_list:
                visit(dec)
            if isinstance(node, ast.ClassDef):
                for b in node.bases:
                    visit(b)
                for kw in node.keywords:
                    visit(kw)
            else:
                for d in list(node.args.defaults) + [kd for kd in node.args.kw_defaults if kd is not None]:
                    visit(d)
            s_outer = clone_state()
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                for p_name in _params(node):
                    kill_alias(p_name)
            for stmt in node.body:
                visit(stmt)
            restore_state(s_outer)
            kill_alias(node.name)
            return
        if isinstance(node, ast.Delete):
            for t in node.targets:
                if isinstance(t, ast.Name) and t.id in bound:
                    kill_alias(t.id)
                else:
                    visit(t)
            return
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and _holder(node.func.value) in bound:
            vals = ([a.value if isinstance(a, ast.Starred) else a for a in node.args]
                    + [k.value for k in node.keywords])
            for m in alias_groups[_holder(node.func.value)]:
                for v in vals:
                    add_write(m, v)
        elif isinstance(node, (ast.Assign, ast.AnnAssign, ast.AugAssign, ast.NamedExpr)) and node.value is not None:
            visit(node.value)
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            for t in targets:
                if isinstance(t, (ast.Subscript, ast.Attribute)) and _holder(t) in bound:
                    visit(t)
                    for m in alias_groups[_holder(t)]:
                        add_write(m, node.value)
                elif isinstance(node, ast.AugAssign) and isinstance(t, ast.Name) and t.id in bound:
                    for m in alias_groups[t.id] - {t.id}:
                        add_write(m, node.value)
                elif isinstance(t, ast.Name) and t.id in bound:
                    if isinstance(node.value, ast.Name):
                        bind_alias(t.id, node.value.id)
                    else:
                        kill_alias(t.id)
                elif isinstance(t, (ast.Tuple, ast.List)):
                    for sub in ast.walk(t):
                        if isinstance(sub, ast.Name) and sub.id in bound:
                            kill_alias(sub.id)
                else:
                    visit(t)
            return
        for child in ast.iter_child_nodes(node):
            visit(child)

    visit(fn)
    _WRITES[id(fn)] = (fn, out)
    return out

